parameters.jsCode:
const item = $input.first().json;
const raw = item.output || '';
const cleaned = raw.replace(/```json|```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    categorie: 'URGENCE_HUMAINE',
    nom_patient: '',
    motif: '',
    urgence: 'ELEVE',
    resume: 'Erreur de classification automatique par IA, a verifier manuellement.',
    date_souhaitee: '',
    heure_souhaitee: '',
    telephone: '',
    type_consultation: ''
  };
}

const fromHeader = ($('Gmail Trigger').first().json.From) || '';
const match = fromHeader.match(/^"?([^"<]+?)"?\s*<([^>]+)>/);
const headerName = match ? match[1].trim() : '';
const headerEmail = match ? match[2].trim() : fromHeader.trim();

const nomFinal = headerName || parsed.nom_patient || '';

return [{ json: { ...item, ...parsed, nom_patient: nomFinal, patient_email: headerEmail } }];

const events = $input.all().map(i => i.json).filter(e => e && (e.start || e.end));

const horaires = {
  1: [[9,0,13,0],[14,0,19,0]],
  2: [[9,0,13,0],[14,0,18,0]],
  3: [[9,0,13,0],[14,0,18,0]],
  4: [[9,0,13,0],[14,0,17,0]],
  5: [[9,0,13,0],[14,0,17,0]]
};

const slotMinutes = 30;
const NAIROBI_OFFSET_HOURS = 3;
const MAX_SLOTS_PER_DAY = 3;
const MIN_DAYS_WITH_SLOTS = 3;
const MAX_DAYS_TO_SCAN = 14;

const busy = events.map(e => {
  const s = e.start && (e.start.dateTime || e.start.date);
  const en = e.end && (e.end.dateTime || e.end.date);
  return (s && en) ? { start: new Date(s), end: new Date(en) } : null;
}).filter(Boolean);

function overlaps(s1, e1, s2, e2) {
  return s1 < e2 && s2 < e1;
}

const noms = ['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'];
const moisNoms = ['janvier','fevrier','mars','avril','mai','juin','juillet','aout','septembre','octobre','novembre','decembre'];
const now = new Date();
const nairobiNow = new Date(now.getTime() + NAIROBI_OFFSET_HOURS*3600000);

const jours = [];
let daysWithSlots = 0;

for (let d = 0; d < MAX_DAYS_TO_SCAN && daysWithSlots < MIN_DAYS_WITH_SLOTS; d++) {
  const dayRef = new Date(nairobiNow.getTime() + d*86400000);
  const y = dayRef.getUTCFullYear();
  const mo = dayRef.getUTCMonth();
  const dt = dayRef.getUTCDate();
  const dow = dayRef.getUTCDay();
  const plages = horaires[dow];
  if (!plages) continue;

  const slotsDuJour = [];
  for (const [h1,m1,h2,m2] of plages) {
    let curH = h1, curM = m1;
    while ((curH < h2 || (curH === h2 && curM < m2)) && slotsDuJour.length < MAX_SLOTS_PER_DAY) {
      let endH = curH, endM = curM + slotMinutes;
      if (endM >= 60) { endH += Math.floor(endM/60); endM = endM % 60; }
      if (endH > h2 || (endH === h2 && endM > m2)) break;

      const slotStartUTC = new Date(Date.UTC(y, mo, dt, curH - NAIROBI_OFFSET_HOURS, curM));
      const slotEndUTC = new Date(Date.UTC(y, mo, dt, endH - NAIROBI_OFFSET_HOURS, endM));

      if (slotStartUTC > now) {
        const isBusy = busy.some(b => overlaps(slotStartUTC, slotEndUTC, b.start, b.end));
        if (!isBusy) {
          const heureStr = String(curH).padStart(2,'0') + 'h' + String(curM).padStart(2,'0');
          slotsDuJour.push(heureStr);
        }
      }
      curH = endH; curM = endM;
    }
  }

  if (slotsDuJour.length > 0) {
    const jourNom = noms[dow];
    jours.push(jourNom + ' ' + dt + ' ' + moisNoms[mo] + ' : ' + slotsDuJour.join(', '));
    daysWithSlots++;
  }
}

return [{ json: { creneauxDisponibles: jours.length ? jours.join('\n') : 'Aucun creneau trouve dans les prochains jours, merci de contacter directement le cabinet.' } }];

