const item = $input.first().json;
const horaires = {
  1: [[9,0,13,0],[14,0,19,0]],
  2: [[9,0,13,0],[14,0,18,0]],
  3: [[9,0,13,0],[14,0,18,0]],
  4: [[9,0,13,0],[14,0,17,0]],
  5: [[9,0,13,0],[14,0,17,0]]
};

const dateStr = item.date_souhaitee;
const heureStr = item.heure_souhaitee;

let horaires_valides = false;

if (dateStr && heureStr) {
  const [y, m, d] = dateStr.split('-').map(Number);
  const [h, min] = heureStr.split(':').map(Number);
  const dateObj = new Date(Date.UTC(y, m - 1, d));
  const dow = dateObj.getUTCDay();
  const plages = horaires[dow];
  if (plages) {
    const minutesDemandees = h * 60 + min;
    horaires_valides = plages.some(([h1,m1,h2,m2]) => {
      const debut = h1*60+m1;
      const fin = h2*60+m2 - 30;
      return minutesDemandees >= debut && minutesDemandees <= fin;
    });
  }
}

return [{ json: { ...item, horaires_valides } }];
